{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 모범이 되는 청년을 서울시가 표창할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시는 다른 사람에게 모범이 되는 청년을 표창할 수 있다. 서울특별시 청년 기본 조례 제25조는 시장이 다른 사람에게 모범이 되는 청년 또는 청년발전에 관하여 현저한 공로가 있다고 인정되는 개인 또는 단체에 대하여 「서울특별시 표창 조례」에 따라 표창할 수 있다고 정하고 있다. 따라서 모범이 되는 청년은 표창 대상에 해당한다.",
          "b_ids": "청년:제25조"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
